import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.shared.aashell.genericaashell import GenericAashell

__author__ = "Piotr Smerdzynski"
__copyright__ = "Copyright (C) 2019, Nokia"
__email__ = "piotr.smerdzynski@nokia.com"


class Proc(GenericAashell):
    """Proc command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Command proc.

        :param connection: moler connection to device, terminal when command is executed
        :param options: parameter with which the command will be executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Proc, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret["RESULT"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "proc"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_running_processes(line)
                self._parse_processes_verbose(line)
                self._parse_commands_for_process(line)
            except ParsingDone:
                pass
        return super(Proc, self).on_new_line(line, is_full_line)

    _re_processes = re.compile(r"^\w+$")

    def _parse_running_processes(self, line):
        """
        Add process name to result list.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(Proc._re_processes, line) and not self._regex_helper.group(0).startswith("live"):
            if not self.current_ret["RESULT"].get("processes"):
                self.current_ret["RESULT"]["processes"] = []
            self.current_ret["RESULT"]["processes"].append(self._regex_helper.group(0))
            raise ParsingDone

    _re_verbose_processes = re.compile(r"^(?P<eeName>\S+)\s+\|\s(?P<eeId>0x\S+)\s+\|\s(?P<euId>0x\S+)")

    def _parse_processes_verbose(self, line):
        """
        Parse process names and corresponding eeId and euId.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(Proc._re_verbose_processes, line):
            self.current_ret["RESULT"][self._regex_helper.group("eeName")] = {}
            self.current_ret["RESULT"][self._regex_helper.group("eeName")]["eeId"] = self._regex_helper.group("eeId")
            self.current_ret["RESULT"][self._regex_helper.group("eeName")]["eeId_raw"] = int(self._regex_helper.group("eeId"), 16)
            self.current_ret["RESULT"][self._regex_helper.group("eeName")]["euId"] = self._regex_helper.group("euId")
            self.current_ret["RESULT"][self._regex_helper.group("eeName")]["euId_raw"] = int(self._regex_helper.group("euId"), 16)
            raise ParsingDone

    _re_commands_for_processes = re.compile(r"^(\?|[a-z]+[a-zA-Z_]+)")

    def _parse_commands_for_process(self, line):
        """
        Parse available commands for corresponding process.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(Proc._re_commands_for_processes, line):
            if self._regex_helper.group(0) == "eeName":
                return
            process_name = self.current_ret["RESULT"]["processes"][-1]
            if process_name not in self.current_ret["RESULT"]:
                self.current_ret["RESULT"][process_name] = []
            self.current_ret["RESULT"][process_name].append(self._regex_helper.group(0))
            raise ParsingDone


